def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([0]), fmt([-5, -5]), fmt([1, 2]), fmt([2, 1]), fmt([-10**9, 10**9, -10**9, 10**9]),
             fmt([3, 3, 3, 4, 3]), fmt([5, 4, 3, 2, 1]), fmt([1, 2, 3, 4, 5])]
    for n in (3, 5, 8, 12, 20, 30):
        for _ in range(3):
            tests.append(fmt([rng.randint(-5, 5) for _ in range(n)]))
    for _ in range(3):
        tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(rng.randint(5, 20))]))
    N = 10**5
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt([10**9 - i for i in range(N)]))
    tests.append(fmt([-10**9 + i for i in range(N)]))
    tests.append(fmt([7] * N))
    tests.append(fmt([(10**9 - i) if i % 2 == 0 else (-10**9 + i) for i in range(N)]))
    tests.append(fmt([rng.randint(1, 3) for _ in range(N)]))
    return tests
